  <script>
    const categories = ["Profile","Wallet","Welcome","Account Setup","Home","Subscription & Paywall","Login","Settings","Checkout","Collections"];
    const tabs = ["screens","elements","flows","text"];
    const filterRow = document.getElementById('filterRow');
    const searchGrid = document.getElementById('searchGrid');
    let activeCategory = categories[0];
    let activeTab = 'screens';

    function buildFilters() {
      filterRow.innerHTML = categories.map(c => `<button class="pill ${c===activeCategory?'active':''}" data-cat="${c}">${c}</button>`).join('');
      filterRow.querySelectorAll('.pill').forEach(btn => {
        btn.addEventListener('click', () => {
          activeCategory = btn.dataset.cat;
          buildFilters();
          buildGrid();
        });
      });
    }

    function buildGrid() {
      const labels = {
        screens: 'Screen',
        elements: 'Element',
        flows: 'Flow Step',
        text: 'Extracted Copy'
      };
      searchGrid.style.opacity = 0;
      setTimeout(() => {
        searchGrid.innerHTML = Array.from({ length: 8 }).map((_, i) => `
          <article class="shot" data-label="${labels[activeTab]} · ${activeCategory} · ${i+1}"></article>
        `).join('');
        searchGrid.style.opacity = 1;
      }, 140);
    }

    document.querySelectorAll('.tab').forEach(tab => {
      tab.addEventListener('click', () => {
        document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        activeTab = tab.dataset.tab;
        buildGrid();
      });
    });

    const flowContent = document.getElementById('flowContent');
    function renderFlow(mode='videos') {
      flowContent.style.opacity = 0;
      setTimeout(() => {
        if (mode === 'videos') {
          flowContent.innerHTML = ["Onboarding walkthrough","Checkout recovery flow","Upgrade funnel"]
            .map(item => `<article class="shot" data-label="Video · ${item}" style="min-height:180px"></article>`).join('');
        } else {
          flowContent.innerHTML = ["Step 1: Welcome","Step 2: Personalize","Step 3: Confirm","Step 4: Trial","Step 5: Paywall","Step 6: Activation"]
            .map(item => `<article class="shot" data-label="Prototype · ${item}" style="min-height:120px"></article>`).join('');
        }
        flowContent.style.opacity = 1;
      }, 130);
    }
    document.querySelectorAll('.flow-mode').forEach(modeBtn => {
      modeBtn.addEventListener('click', () => {
        document.querySelectorAll('.flow-mode').forEach(m => m.classList.remove('active'));
        modeBtn.classList.add('active');
        renderFlow(modeBtn.dataset.mode);
      });
    });

    function animateCounter(el, target, duration = 1400, delay = 0) {
      setTimeout(() => {
        const start = performance.now();
        const from = 0;
        function tick(now) {
          const progress = Math.min((now - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const value = Math.floor(from + (target - from) * eased);
          el.textContent = value.toLocaleString();
          if (progress < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      }, delay);
    }

    const statsSection = document.getElementById('stats');
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const counters = statsSection.querySelectorAll('.stat-number');
          counters.forEach((counter, index) => animateCounter(counter, Number(counter.dataset.target), 1500, index * 140));
          observer.disconnect();
        }
      });
    }, { threshold: 0.3 });
    observer.observe(statsSection);

    const testimonials = [
      ["ScreenVault is my first stop when I start a new product surface.","Sebastian Speier","Product Designer"],
      ["The flow coverage is insane — it saves us hours every week.","Meng To","Design Educator"],
      ["Search by UI text is a game changer for edge cases.","Marco Cornacchia","Design Lead"],
      ["Fast, clean, and reliably up to date.","Daryl Ginn","Founder"],
      ["Our team uses collections in every sprint planning session.","Rachel How","Senior Product Designer"],
      ["Prototype mode helped us redesign onboarding in one afternoon.","Haerin Song","UX Designer"]
    ];

    function quoteCard(item) {
      return `<article class="quote"><p>“${item[0]}”</p><strong>${item[1]}</strong><span>${item[2]}</span></article>`;
    }
    document.getElementById('trow1').innerHTML = [...testimonials, ...testimonials].map(quoteCard).join('');
    document.getElementById('trow2').innerHTML = [...testimonials.slice().reverse(), ...testimonials.slice().reverse()].map(quoteCard).join('');

    buildFilters();
    buildGrid();
    renderFlow();
  </script>
